import {shuffle,createSession,recordAnswer,advance,firstAttemptScore,updateProgress} from './engine.mjs';
const root=document.querySelector('#app');
const KEY='midterm-lab-v1';
const LECTURE=['','1','2','3–4','5','6','7'];
let data,warning='',view='home';
let state={progress:{},session:null};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const byId=id=>data.find(q=>q.id===id);
function save(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch{warning='Браузер не разрешил сохранение. Текущая сессия продолжится, пока открыта вкладка.'}}
try{const raw=JSON.parse(localStorage.getItem(KEY)||'null');if(raw?.progress&&typeof raw.progress==='object'&&!Array.isArray(raw.progress)){state.progress=raw.progress;state.session=raw.session||null}}catch{warning='Не удалось прочитать сохранение. Можно начать новый квиз.'}
function shell(body){root.innerHTML=`<main class="app"><header><span class="brand">midterm<span>lab</span></span><span class="course">Mobile Security</span></header>${warning?`<p class="warning" role="status">${esc(warning)}</p>`:''}${body}</main>`;root.querySelector('[data-start]')?.addEventListener('click',start);root.querySelectorAll('[data-choice]').forEach(el=>el.addEventListener('click',()=>answer(el.dataset.choice)));root.querySelector('[data-next]')?.addEventListener('click',next)}
function home(){const s=state.session;const resume=s&&!s.done;shell(`<section class="welcome"><span class="label">ЛЕКЦИИ 1–7 · 67 ВОПРОСОВ</span><h1>Подготовка<br>к Midterm</h1><p>Выбери ответ — объяснение появится снизу.<br>Ошибёшься — вопрос вернётся через два других.</p><button class="primary" data-start>Начать экзамен <span aria-hidden="true">→</span></button><small>${resume?'Продолжим с сохранённого вопроса.':'Вопросы и варианты перемешиваются автоматически.'}</small></section>`)}
function start(){if(!state.session||state.session.done){state.session=createSession(data.map(q=>q.id),{mode:'practice',random:true})}view='quiz';save();render();window.scrollTo(0,0)}
function source(q){return q.sources.map(s=>`${esc(s.file)} · слайд${s.slides.length>1?'ы':''} ${s.slides.join(', ')}`).join(' / ')}
function quiz(){const s=state.session;if(s.done){result();return}const q=byId(s.queue[s.index]);if(!s.options.length){s.options=shuffle(q.options.map(o=>o.id));save()}const answered=s.current;const completed=new Set(s.answers.map(a=>a.id)).size;const remaining=s.queue.length-s.index-(answered?1:0);const repeat=s.answers.slice(0,answered?-1:undefined).some(a=>a.id===q.id);shell(`<section class="quiz"><div class="progress-meta"><span>Пройдено ${completed} из ${s.total}</span><span>Лекция ${LECTURE[q.section]}</span></div><div class="progress" role="progressbar" aria-label="Пройденные вопросы" aria-valuenow="${completed}" aria-valuemin="0" aria-valuemax="${s.total}"><span style="width:${Math.round(completed/s.total*100)}%"></span></div><article class="question"><div class="label">${repeat?'↻ ПОВТОР ВОПРОСА':'ВОПРОС'} · SAMPLE №${q.number}</div><h1>${esc(q.question)}</h1><div class="options">${s.options.map((id,i)=>{const o=q.options.find(o=>o.id===id);const right=answered&&id===q.correct,wrong=answered&&id===answered.choice&&!answered.correct;return `<button class="option ${right?'correct':''} ${wrong?'wrong':''}" data-choice="${id}" ${answered?'disabled':''}><span class="letter">${i+1}</span><span>${esc(o.text)}</span>${right?'<span class="mark" aria-label="Правильный ответ">✓</span>':wrong?'<span class="mark" aria-label="Неверный ответ">×</span>':''}</button>`}).join('')}</div>${answered?`<section class="feedback ${answered.correct?'':'error'}" role="status" aria-label="Объяснение ответа"><strong>${answered.correct?'✓ Правильно':'↻ Неверно — запомним'}</strong>${!answered.correct?`<p class="right-answer">Правильный ответ: <b>${esc(q.options.find(o=>o.id===q.correct).text)}</b></p>`:''}<p>${esc(q.explanation)}</p>${q.note?`<p class="note">${esc(q.note)}</p>`:''}<p class="source">${source(q)}</p>${q.external?`<a class="source" href="${esc(q.external)}" target="_blank" rel="noopener noreferrer">Источник уточнения ↗</a>`:''}${!answered.correct?'<p class="repeat-hint">Вопрос вернётся через два других. Если очередь заканчивается — раньше.</p>':''}</section>`:''}<div class="next-wrap"><button class="primary" data-next ${answered?'':'disabled'}>${answered&&remaining===0?'Завершить':'Следующий вопрос'} <span aria-hidden="true">→</span></button></div>${!answered?'<p class="quiet">Выбери один из четырёх вариантов</p>':''}</article></section>`)}
function answer(choice){if(view!=='quiz')return;const s=state.session;if(s.done||s.current)return;const q=byId(s.queue[s.index]);if(!q.options.some(o=>o.id===choice))return;if(recordAnswer(s,q,choice)){state.progress=updateProgress(state.progress,q.id,choice===q.correct);save();render();root.querySelector('.feedback')?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'nearest'})}}
function next(){if(view!=='quiz'||!advance(state.session))return;if(state.session.done)state.session.finishedAt=Date.now();save();render();window.scrollTo({top:0,behavior:'instant'})}
function result(){const s=state.session,score=firstAttemptScore(s.answers);shell(`<section class="welcome"><span class="label">ЭКЗАМЕН ЗАВЕРШЁН</span><h1>Все вопросы<br>пройдены.</h1><p>С первого раза: <b>${score.correct} из ${score.total}</b>.<br>Все неверные ответы повторены и закреплены.</p><button class="primary" data-start>Начать экзамен <span aria-hidden="true">→</span></button><small>Новый порядок вопросов и вариантов.</small></section>`)}
function render(){if(view==='quiz')quiz();else home()}
function validSession(s){return s&&s.mode==='practice'&&s.total===data.length&&Array.isArray(s.queue)&&s.queue.every(id=>byId(id))&&Number.isInteger(s.index)&&s.index>=0&&s.index<=s.queue.length&&Array.isArray(s.answers)&&s.answers.every(a=>byId(a.id)&&typeof a.correct==='boolean')&&Array.isArray(s.history)&&Array.isArray(s.options)&&s.options.every(id=>['0','1','2','3'].includes(id))&&(s.current===null||typeof s.current==='object')}
try{const res=await fetch('questions.json');if(!res.ok)throw Error();data=await res.json();if(!validSession(state.session))state.session=null;render()}catch{root.innerHTML='<p class="loading" role="alert">Не удалось загрузить вопросы. Проверь подключение и обнови страницу.</p>'}
// Keep the previous session format so existing full-quiz progress can resume.
document.addEventListener('keydown',e=>{if(e.ctrlKey||e.metaKey||e.altKey||e.repeat||view!=='quiz'||!state.session||state.session.done)return;const s=state.session;if(/^[1-4]$/.test(e.key)&&!s.current){e.preventDefault();answer(s.options[Number(e.key)-1])}else if(e.key==='Enter'&&s.current&&e.target.tagName!=='BUTTON'){e.preventDefault();next()}});
if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
